# v1.0.4

using Markdown
using InteractiveUtils

# This Pluto notebook uses @bind for interactivity. When running this notebook outside of Pluto, the following 'mock version' of @bind gives bound variables a default value (instead of an error).
macro bind(def, element)
    #! format: off
    return quote
        local iv = try Base.loaded_modules[Base.PkgId(Base.UUID("6e696c72-6542-2067-7265-42206c756150"), "AbstractPlutoDingetjes")].Bonds.initial_value catch; b -> missing; end
        local el = $(esc(element))
        global $(esc(def)) = Core.applicable(Base.get, el) ? Base.get(el) : iv(el)
        el
    end
    #! format: on
end

# ╔═╡ b047a994-7174-4941-a972-000000000001
md"""# Oxygen: plan, compare and investigate
Open this downloaded `.jl` with **Open a notebook** in Pluto's browser UI. The preparation cell installs registered Core 1.1.0, Makie/Pluto companions 1.0.1 and the declared controller packages. Its self-contained runtime lives under `~/.julia/dev/PerfCheckerNotebookExamples/oxygen`; set `PERFCHECKER_OXYGEN_NOTEBOOK_ROOT` to choose another empty directory. First opening needs internet access.

The notebook embeds the workload, independent oracles and real saved measurements. It needs no PerfChecker checkout or relative website assets. Preparing dependencies, changing selectors and rendering saved results start no measurement. Review the plan before **Launch selected checks**."""

# ╔═╡ b047a994-7174-4941-a972-000000000002
begin
    import Pkg, TOML
    notebook_root = get(ENV, "PERFCHECKER_OXYGEN_NOTEBOOK_ROOT", joinpath(homedir(), ".julia", "dev", "PerfCheckerNotebookExamples", "oxygen"))
    controller_project = joinpath(notebook_root, "controller")
    Pkg.activate(controller_project; io=devnull)
    package_specs = [Pkg.PackageSpec(name="PerfChecker",version="1.1.0"),Pkg.PackageSpec(name="PerfCheckerMakie",version="1.0.1"),Pkg.PackageSpec(name="PerfCheckerPluto",version="1.0.1"),Pkg.PackageSpec(name="PlutoUI",version="0.7.83"),Pkg.PackageSpec(name="BenchmarkTools",version="1.7.0"),Pkg.PackageSpec(name="Chairmarks",version="1.3.1"),Pkg.PackageSpec(name="WGLMakie",version="0.13.15"),Pkg.PackageSpec(name="JSON",version="1"),Pkg.PackageSpec(name="UnicodePlots",version="3")]
    declared = isfile(joinpath(controller_project,"Project.toml")) ? get(TOML.parsefile(joinpath(controller_project,"Project.toml")),"deps",Dict()) : Dict()
    any(spec -> !haskey(declared,spec.name),package_specs) && Pkg.add(package_specs)
    using PerfChecker, PerfCheckerMakie, PerfCheckerPluto, PlutoUI, BenchmarkTools, Chairmarks, WGLMakie, JSON, UnicodePlots
    @assert pkgversion(PerfChecker)==v"1.1.0"
    @assert pkgversion(PerfCheckerMakie)==v"1.0.1"
    @assert pkgversion(PerfCheckerPluto)==v"1.0.1"
    WGLMakie.activate!()
    runtime_sources = Dict("oxygen/counter.jl" => "include(joinpath(@__DIR__, \"service.jl\"))\nconst request_lifecycle = EventService.request_case(\"counter\")\nperf_setup() = request_lifecycle.prepare()\nperf_workload(state) = request_lifecycle.operation(state)\nperf_oracle(state, result) = request_lifecycle.verify(state, result)\n", "oxygen/features/not_found.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"not_found\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "oxygen/features/binary.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"binary\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "oxygen/features/json.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"json\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "oxygen/features/query.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"query\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "oxygen/features/html.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"html\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "oxygen/suite.jl" => "using PerfChecker\n# One point per older minor series; every patch in the two latest minor series.\n# Keep this explicit: rerunning the example must not silently select new releases.\nconst OXYGEN_VERSIONS = vcat([VersionNumber(1, minor, 0) for minor in 0:9],\n    [v\"1.10.0\", v\"1.10.1\", v\"1.10.2\", v\"1.11.0\"])\n\n\"Compare the same in-process HTTP requests from Oxygen's first release to HTTP.jl 2.\"\nfunction build_suite()\n    features = FeatureSpec[]\n    for kind in (\"heap\", \"counter\", \"buffer\"),\n        backend in (:benchmark, :chairmark, :profile, :wall_profile, :profile_alloc)\n\n        push!(features,\n            FeatureSpec(Symbol(kind, \"_\", backend);\n                workload = Symbol(kind, \"_request\"), backend,\n                entrypoint = joinpath(@__DIR__, kind * \".jl\"),\n                comparison_key = \"oxygen/events/\$(kind)/2048/seed42/v1\",\n                oracle = OracleSpec(), state_policy = :fresh,\n                options = Dict(\n                    :threads => 1, :samples => 30, :evals => 1, :seconds => 0.25)))\n    end\n    package = PackageSuite(\"Oxygen\"; worker_environment = joinpath(@__DIR__, \"workers\"),\n        versions = OXYGEN_VERSIONS, include_dev = false, features)\n    SoftwareSuite(:oxygen_event_lab, [package];\n        description = \"Oxygen router, JSON decoding, event processing and response encoding; no socket\")\nend\n", "src/PerfCheckerKitchenSink.jl" => "module PerfCheckerKitchenSink\nusing DataStructures\nusing Random\n\nexport events, drain_heap, drain_vector, count_events, recent_events, event_case\n\n# Select the public constructor once, outside measurement. Older releases used\n# a lowercase function for the same min-heap operation.\nconst make_minheap = isdefined(DataStructures, :BinaryMinHeap) ?\n                     DataStructures.BinaryMinHeap : DataStructures.binary_minheap\n\n\"Generate immutable (priority, unique id, category) events from a fixed seed.\"\nfunction events(n::Integer = 2048; seed::Integer = 42)\n    n >= 0 || throw(ArgumentError(\"event count must be nonnegative\"))\n    rng = Random.Xoshiro(seed)\n    return [(rand(rng, 1:max(n, 1)), i, rand(rng, 1:16)) for i in 1:n]\nend\n\n\"Build and drain a binary heap; input generation is outside this operation.\"\nfunction drain_heap(input)\n    queue = make_minheap(input)\n    output = similar(input, 0)\n    sizehint!(output, length(input))\n    while !isempty(queue)\n        push!(output, pop!(queue))\n    end\n    return output\nend\n\n\"A deliberately simple sorted-vector queue with the same output as drain_heap.\"\nfunction drain_vector(input)\n    queue = sort(input)\n    output = similar(input, 0)\n    sizehint!(output, length(input))\n    while !isempty(queue)\n        push!(output, popfirst!(queue))\n    end\n    return output\nend\n\n\"Count categories using an Accumulator and return an ordinary dictionary.\"\ncount_events(input) = Dict(counter(event[3] for event in input))\n\n\"Retain the last 64 events in arrival order using a circular buffer.\"\nfunction recent_events(input)\n    buffer = CircularBuffer{eltype(input)}(64)\n    append!(buffer, input)\n    return collect(buffer)\nend\n\n\"One oracle-bearing lifecycle shared by correctness tests, scenarios and suite workers.\"\nfunction event_case(parameters)\n    n = Int(get(parameters, \"n\", 2048))\n    input = events(n; seed = Int(get(parameters, \"seed\", 42)))\n    kind = String(get(parameters, \"kind\", \"heap\"))\n    operation = kind == \"heap\" ? drain_heap :\n                kind == \"vector\" ? drain_vector :\n                kind == \"counter\" ? count_events :\n                kind == \"buffer\" ? recent_events :\n                throw(ArgumentError(\"Choose heap, vector, counter or buffer\"))\n    expected = if kind in (\"heap\", \"vector\")\n        sort(input)\n    elseif kind == \"counter\"\n        Dict(category => count(e -> e[3] == category, input)\n        for category in unique(e[3] for e in input))\n    else\n        input[max(1, length(input) - 63):end]\n    end\n    return (prepare = () -> copy(input), operation = operation,\n        verify = (state, result) -> result == expected && state == input)\nend\nend\n", "oxygen/service.jl" => "module EventService\nimport Oxygen\nimport HTTP, JSON\n# Oxygen renamed the macro between the historical releases in this example.\nif isdefined(Oxygen, Symbol(\"@oxidize\"))\n    Core.eval(@__MODULE__, :(Oxygen.@oxidize))\nelseif isdefined(Oxygen, Symbol(\"@oxidise\"))\n    Core.eval(@__MODULE__, :(Oxygen.@oxidise))\nelse\n    # Early Oxygen releases have a process-global router. Suite workers are\n    # isolated processes, so these routes cannot modify the Web interface (Oxygen).\n    Core.eval(@__MODULE__, :(using Oxygen))\nend\ninclude(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nusing .PerfCheckerKitchenSink\n\n# HTTP versions can return either immutable strings or mutable byte vectors.\n# Copy bytes before String conversion because that conversion can take ownership.\nbody_text(body::AbstractString) = String(body)\nbody_text(body) = String(copy(body))\n\n# An independent router avoids changing the Web interface (Oxygen)'s routes when both are loaded.\nfor kind in (\"heap\", \"counter\", \"buffer\")\n    handler = function (request::HTTP.Request)\n        raw = JSON.parse(body_text(request.body))\n        input = [Tuple(Int.(row)) for row in raw]\n        operation = kind == \"heap\" ? drain_heap :\n                    kind == \"counter\" ? count_events : recent_events\n        HTTP.Response(\n            200, [\"Content-Type\" => \"application/json\"]; body = JSON.json(operation(input)))\n    end\n    if isdefined(@__MODULE__, :post)\n        post(handler, \"/events/\" * kind)\n    else\n        # The first releases expose registration only through macros.\n        Core.eval(@__MODULE__, :(Oxygen.@post \$(\"/events/\" * kind) \$handler))\n    end\nend\n\n# The metrics keyword did not exist in the early API. Resolve this once rather\n# than catching keyword errors (or doing reflection) inside timed requests.\nconst supports_metrics = :metrics in Base.kwarg_decl(which(\n    internalrequest, (HTTP.Request,)))\nfunction dispatch_request(request)\n    supports_metrics ? internalrequest(request; metrics = false) : internalrequest(request)\nend\n\n\"Prepare a fixed request and an independent expected response; no socket is opened.\"\nfunction request_case(kind = \"heap\", n = 2048)\n    input = events(n)\n    expected = kind == \"heap\" ? sort(input) :\n               kind == \"buffer\" ? input[max(1, n - 63):end] :\n               Dict(k => count(e -> e[3] == k, input) for k in unique(e[3] for e in input))\n    payload = JSON.json(input)\n    expected_json = JSON.parse(JSON.json(expected))\n    return (\n        prepare = () -> HTTP.Request(\"POST\", \"/events/\" * kind,\n            [\"Content-Type\" => \"application/json\"], payload),\n        operation = dispatch_request,\n        verify = (request, response) -> response.status == 200 &&\n            JSON.parse(body_text(response.body)) == expected_json,\n        payload = payload, expected = expected_json\n    )\nend\n\n\"Start only this example's loopback service. The caller must terminate it in finally.\"\nstart(port = 18872) = serve(; host = \"127.0.0.1\", port, async = true,\n    docs = false, metrics = false, show_banner = false, access_log = nothing)\nstop() = terminate()\n\n\"Parameter dictionary entry point for the shared-scenario runner.\"\nscenario(parameters) = request_case(\n    String(Base.get(parameters, \"kind\", \"heap\")), Int(Base.get(parameters, \"n\", 2048)))\ninclude(joinpath(@__DIR__, \"feature-routes.jl\"))\nend\n", "oxygen/features-suite.jl" => "include(joinpath(@__DIR__, \"suite.jl\"))\nconst HTTP_FEATURE_NAMES = (\"plain\", \"path\", \"query\", \"json\", \"html\", \"binary\", \"not_found\")\n\"Compare routing, parsing and response handling independently across registered patches.\"\nfunction build_http_feature_suite()\n    features = [FeatureSpec(Symbol(kind, \"_benchmark\"); workload = Symbol(kind, \"_http\"),\n                    backend = :benchmark, oracle = OracleSpec(), state_policy = :fresh,\n                    entrypoint = joinpath(@__DIR__, \"features\", kind * \".jl\"),\n                    comparison_key = \"oxygen/http/\$(kind)/v1\",\n                    options = Dict(\n                        :threads => 1, :samples => 30, :evals => 1, :seconds => 0.25))\n                for kind in HTTP_FEATURE_NAMES]\n    SoftwareSuite(:oxygen_http_features,\n        [PackageSuite(\"Oxygen\";\n            versions = OXYGEN_VERSIONS, include_dev = false,\n            worker_environment = joinpath(@__DIR__, \"workers\"), features)];\n        description = \"Separate HTTP features across 14 Oxygen releases, with all 1.10 and 1.11 patches\")\nend\n", "oxygen/workers/Project.toml" => "[deps]\nBenchmarkTools = \"6e4b80f9-dd63-53aa-95a3-0cdb28fa8baf\"\nChairmarks = \"0ca39b1e-fe0b-4e98-acfc-b1656634c4de\"\nDataStructures = \"864edb3b-99cc-5e75-8d2d-829cb0a9cfe8\"\nHTTP = \"cd3eb016-35fb-5094-929b-558a96fad6f3\"\nJSON = \"682c06a0-de6a-54ab-a142-c8b1cf79cde6\"\n\n[compat]\nBenchmarkTools = \"1\"\nChairmarks = \"1\"\nHTTP = \"0.9, 1, 2\"\nJSON = \"1\"\n", "oxygen/features/path.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"path\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "oxygen/heap.jl" => "include(joinpath(@__DIR__, \"service.jl\"))\nconst request_lifecycle = EventService.request_case(\"heap\")\nperf_setup() = request_lifecycle.prepare()\nperf_workload(state) = request_lifecycle.operation(state)\nperf_oracle(state, result) = request_lifecycle.verify(state, result)\n", "oxygen/feature-routes.jl" => "# Included inside EventService after creating its isolated Oxygen router.\n# These public route macros also existed in Oxygen 1.0.\nCore.eval(@__MODULE__,\n    quote\n        @get \"/features/plain\" function (req::HTTP.Request)\n            \"ready\"\n        end\n        @get \"/features/add/{a}/{b}\" function (req::HTTP.Request, a::Int, b::Int)\n            a + b\n        end\n        @get \"/features/query\" function (req::HTTP.Request)\n            parameters = Oxygen.queryparams(req)\n            parse(Int, parameters[\"a\"]) + parse(Int, parameters[\"b\"])\n        end\n        @get \"/features/json\" function (req::HTTP.Request)\n            Dict(\"ready\" => true, \"values\" => collect(1:64))\n        end\n        @get \"/features/html\" function (req::HTTP.Request)\n            Oxygen.html(\"<p>ready</p>\")\n        end\n        @post \"/features/binary\" function (req::HTTP.Request)\n            HTTP.Response(200; body = Oxygen.binary(req))\n        end\n    end)\n\nconst HTTP_FEATURES = (\"plain\", \"path\", \"query\", \"json\", \"html\", \"binary\", \"not_found\")\n\n\"One isolated HTTP feature with a fixed request and an independently known response.\"\nfunction feature_case(kind::AbstractString)\n    target, payload, expected, status = if kind == \"plain\"\n        (\"/features/plain\", \"\", \"ready\", 200)\n    elseif kind == \"path\"\n        (\"/features/add/19/23\", \"\", \"42\", 200)\n    elseif kind == \"query\"\n        (\"/features/query?a=19&b=23\", \"\", \"42\", 200)\n    elseif kind == \"json\"\n        (\"/features/json\", \"\", Dict(\"ready\" => true, \"values\" => collect(1:64)), 200)\n    elseif kind == \"html\"\n        (\"/features/html\", \"\", \"<p>ready</p>\", 200)\n    elseif kind == \"binary\"\n        bytes = repeat(\"0123456789abcdef\", 256)\n        (\"/features/binary\", bytes, bytes, 200)\n    elseif kind == \"not_found\"\n        (\"/features/does-not-exist\", \"\", nothing, 404)\n    else\n        throw(ArgumentError(\"Unknown HTTP feature: \$kind\"))\n    end\n    return (\n        prepare = () -> HTTP.Request(kind == \"binary\" ? \"POST\" : \"GET\", target, [], payload),\n        operation = dispatch_request,\n        verify = (_, response) -> response.status == status &&\n            (expected === nothing ||\n             (kind == \"json\" ? JSON.parse(body_text(response.body)) == expected :\n              body_text(response.body) == expected)),\n        payload = payload, target = target)\nend\n", "oxygen/buffer.jl" => "include(joinpath(@__DIR__, \"service.jl\"))\nconst request_lifecycle = EventService.request_case(\"buffer\")\nperf_setup() = request_lifecycle.prepare()\nperf_workload(state) = request_lifecycle.operation(state)\nperf_oracle(state, result) = request_lifecycle.verify(state, result)\n", "oxygen/features/plain.jl" => "include(joinpath(@__DIR__, \"../service.jl\"))\nconst lifecycle = EventService.feature_case(\"plain\")\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n")
    for (relative,source) in runtime_sources
        destination=joinpath(notebook_root,relative)
        mkpath(dirname(destination))
        if isfile(destination)
            read(destination,String)==source || error("Notebook workload was edited: "*destination*". Preserve it and choose another notebook root.")
        else
            write(destination,source)
        end
    end
    (controller=Base.active_project(),core=pkgversion(PerfChecker),makie=pkgversion(PerfCheckerMakie),pluto_companion=pkgversion(PerfCheckerPluto),workers_started=false)
end

# ╔═╡ b047a994-7174-4941-a972-000000000003
begin
    struct NotebookActionButton
        label::String
    end
    Base.get(::NotebookActionButton)=""
    function Base.show(io::IO,::MIME"text/html",button::NotebookActionButton)
        label=replace(button.label,'&'=>"&amp;",'<'=>"&lt;",'>'=>"&gt;")
        print(io,"<span><button type='button'>",label,"</button><script>const span=currentScript.parentElement;span.value='';span.firstElementChild.addEventListener('click',event=>{span.value=crypto.randomUUID();span.dispatchEvent(new CustomEvent('input'));event.stopPropagation()});</script></span>")
    end
    last_launch=Ref("");last_cancel=Ref("");last_save=Ref("")
    active_job=Ref{Any}(nothing);last_saved=Ref("")
end

# ╔═╡ b047a994-7174-4941-a972-000000000004
md"""## Prepare a real suite
**Experiment** $( @bind campaign Select(["HTTP features", "Application routes"]))

The suite pins registered target releases. It stores fresh-state preparation and independent verification alongside each workload. Oxygen requests run inside isolated target workers and open no socket; the notebook's Pluto controller does not load Oxygen."""

# ╔═╡ b047a994-7174-4941-a972-000000000005
@bind collector Select(campaign=="HTTP features" ? ["benchmark"] : ["benchmark","chairmark"])

# ╔═╡ b047a994-7174-4941-a972-000000000006
begin
    definition_module=Module(gensym(:OxygenNotebookSuite))
    Core.eval(definition_module, :(include(path)=Base.include($definition_module,path)))
    definition_path=joinpath(notebook_root,campaign=="HTTP features" ? "oxygen/features-suite.jl" : "oxygen/suite.jl")
    Base.include(definition_module,definition_path)
    factory=getfield(definition_module,campaign=="HTTP features" ? :build_http_feature_suite : :build_suite)
    experiment_suite=Base.invokelatest(factory)
    full_plan=filter_suite_plan(plan_suite(experiment_suite;profile=:historical);backends=Symbol(collector))
    features=sort!(unique(string(run.feature.id) for run in full_plan.runs))
    targets=sort!(unique(run.target.version for run in full_plan.runs))
end

# ╔═╡ b047a994-7174-4941-a972-000000000007
md"""**Workload** $(@bind feature Select(features))

**First release** $(@bind first_version Select(string.(targets);default=string(first(targets))))

**Last release** $(@bind last_version Select(string.(targets);default=string(last(targets))))"""

# ╔═╡ b047a994-7174-4941-a972-000000000008
begin
    selected_plan=filter_suite_plan(full_plan;features=[feature],from_version=VersionNumber(first_version),to_version=VersionNumber(last_version))
    Markdown.parse("```text\n"*sprint(print_suite_plan,selected_plan)*"\n```")
end

# ╔═╡ b047a994-7174-4941-a972-000000000009
begin
    first_run=first(selected_plan.runs)
    oracle_source=read(first_run.variant.entrypoint,String)
    Markdown.parse("### The selected lifecycle\nThe target worker loads this entry point. `perf_setup` prepares state; `perf_workload` performs the operation; `perf_oracle` verifies the answer. Inspect the embedded helper source in the notebook runtime for the complete independent oracle.\n\n```julia\n"*oracle_source*"\n```")
end

# ╔═╡ b047a994-7174-4941-a972-000000000010
md"""**Samples** $(@bind samples NumberField(1:10000;default=30))

**Seconds per benchmark** $(@bind seconds NumberField(0.1:0.1:60;default=0.5))

Workers use **one Julia thread** and `evals=1`. Preparation and verification stay outside timing. A narrow release pair is a better starting selection than a complete campaign."""

# ╔═╡ b047a994-7174-4941-a972-000000000011
@bind launch_click NotebookActionButton("Launch selected checks")

# ╔═╡ b047a994-7174-4941-a972-000000000012
job=begin
    if launch_click isa AbstractString && !isempty(launch_click) && launch_click!=last_launch[]
        last_launch[]=launch_click
        active_job[]!==nothing && suite_job_status(active_job[]) ∉ (:complete,:failed,:cancelled) && error("A job is already running; refresh or cancel it first.")
        isempty(selected_plan.runs) && error("Choose a non-empty release range.")
        active_job[]=launch_suite(selected_plan;overrides=Dict{Symbol,Any}(:samples=>samples,:seconds=>seconds,:threads=>1,:evals=>1))
    end
    active_job[]
end

# ╔═╡ b047a994-7174-4941-a972-000000000013
md"""$(@bind refresh_click CounterButton("Refresh status"))

$(@bind cancel_click NotebookActionButton("Cancel active job"))"""

# ╔═╡ b047a994-7174-4941-a972-000000000014
begin
    if cancel_click isa AbstractString && !isempty(cancel_click) && cancel_click!=last_cancel[]
        last_cancel[]=cancel_click
        job===nothing || cancel!(job)
    end
    snapshot=(refresh_click;job===nothing ? Dict("state"=>"idle","completed"=>0,"total"=>0) : suite_job_progress(job))
    HTML("<p role='status'><strong>Status:</strong> "*get(snapshot,"state","idle")*" · "*string(get(snapshot,"completed",0))*" / "*string(get(snapshot,"total",0))*" checks completed</p>")
end

# ╔═╡ b047a994-7174-4941-a972-000000000015
job_result=(snapshot;job===nothing || suite_job_status(job) ∉ (:complete,:failed) ? nothing : wait_suite(job;strict=false))

# ╔═╡ b047a994-7174-4941-a972-000000000016
@bind save_click NotebookActionButton("Save completed reports")

# ╔═╡ b047a994-7174-4941-a972-000000000017
begin
    if save_click isa AbstractString && !isempty(save_click) && save_click!=last_save[]
        last_save[]=save_click
        job_result===nothing && error("Refresh a completed job before saving.")
        reports_root=joinpath(notebook_root,"results");mkpath(reports_root)
        destination=mktempdir(reports_root;prefix="pluto-",cleanup=false)
        write_suite_reports(job_result,destination)
        last_saved[]=destination
    end
    isempty(last_saved[]) ? "No new measurement launched or saved." : "Saved reports: "*last_saved[]
end

# ╔═╡ b047a994-7174-4941-a972-000000000018
begin
    fresh_bundle=job_result===nothing ? nothing : PerfChecker._suite_run_bundle(job_result)
    fresh_entries=fresh_bundle===nothing ? [] : filter(plot_catalog(fresh_bundle)) do entry
        model=performance_plot(fresh_bundle,entry["id"])
        observed=unique(string(row["version"]) for row in model.data if haskey(row,"version"))
        model.kind===:normalized_metrics && length(observed)>=2
    end
    single_target_values=fresh_bundle===nothing ? Any[] : [merge(Dict("workload"=>entry["title"]),row) for entry in plot_catalog(fresh_bundle) if entry["kind"]=="normalized_metrics" for model in (performance_plot(fresh_bundle,entry["id"]),) if length(unique(string(row["version"]) for row in model.data))==1 for row in model.data]
    fresh_status=job_result===nothing ? "No new result: the recorded views below are independent saved evidence." : "New suite correctness passed: "*string(suite_passed(job_result))
end

# ╔═╡ b047a994-7174-4941-a972-000000000019
@bind fresh_view Select(isempty(fresh_entries) ? [""=>"No new multi-release result"] : [entry["id"]=>entry["title"] for entry in fresh_entries])

# ╔═╡ b047a994-7174-4941-a972-000000000020
if !isempty(fresh_view) && fresh_bundle!==nothing
    notebook_plot(performance_plot(fresh_bundle,fresh_view))
elseif isempty(single_target_values)
    Markdown.parse(fresh_status)
else
    Markdown.parse(fresh_status*"\n\n| Workload | Target | Metric | Minimum |\n| --- | --- | --- | --- |\n"*join(["| "*row["workload"]*" | "*row["version"]*" | "*row["metric"]*" | "*string(row["value"])*" "*row["unit"]*" |" for row in single_target_values],"\n"))
end

