    function notebook_plot(model)
        document=performance_plot_html(model)
        escaped=replace(document,'&'=>"&amp;",'"'=>"&quot;",'<'=>"&lt;",'>'=>"&gt;")
        title=replace(model.title,'&'=>"&amp;",'"'=>"&quot;",'<'=>"&lt;",'>'=>"&gt;")
        HTML("<iframe title=\""*title*"\" srcdoc=\""*escaped*"\" style=\"width:100%;height:780px;border:0\" sandbox=\"allow-scripts allow-same-origin allow-downloads\"></iframe>")
    end
    function saved_model(record)
        d=record["plot"]
        PerfChecker.PerformancePlot(d["id"],Symbol(d["kind"]),d["title"],d["description"],Dict{String,Any}(d["encoding"]),Dict{String,Any}[Dict(row) for row in d["data"]],Dict{String,Any}(d["options"]))
    end
