# ╔═╡ b047a994-7174-4941-a972-000000000023
@bind recorded_campaign Select(["HTTP features", "Application routes"])

# ╔═╡ b047a994-7174-4941-a972-000000000024
@bind recorded_choice Select([string(index)=>entry["label"] for (index,entry) in enumerate(recorded_histories[recorded_campaign])])

# ╔═╡ b047a994-7174-4941-a972-000000000025
begin
    history_entry=recorded_histories[recorded_campaign][parse(Int,recorded_choice)]
    history_record=history_entry["record"]
    history_model=saved_model(history_record)
    @assert history_model.kind===:normalized_metrics
    @assert length(unique(string(row["version"]) for row in history_model.data))>=2
    (source_sha256=history_entry["source_sha256"],runtime=get(history_record,"runtime",nothing),collector=history_model.options["collector"],versions=history_model.options["versions"],recorded_rows=length(history_model.data),measurement_started=false)
end

# ╔═╡ b047a994-7174-4941-a972-000000000026
notebook_plot(history_model)

# ╔═╡ b047a994-7174-4941-a972-000000000027
terminal_plot(history_model)

# ╔═╡ b047a994-7174-4941-a972-000000000028
md"""## Latest application diagnostics
These saved profiles describe the **2,048-event heap request at Oxygen 1.11.0**, not the seven small HTTP feature cases and not real socket traffic. Flame width is captured weight rather than chronology. Pies and source lines retain their actual recorded attribution."""

# ╔═╡ b047a994-7174-4941-a972-000000000029
@bind diagnostic_choice Select([string(index)=>entry["label"] for (index,entry) in enumerate(recorded_profiles)])

# ╔═╡ b047a994-7174-4941-a972-000000000030
begin
    diagnostic_entry=recorded_profiles[parse(Int,diagnostic_choice)]
    diagnostic_record=diagnostic_entry["record"]
    diagnostic_model=saved_model(diagnostic_record)
    @assert diagnostic_model.kind in (:cpu_flamegraph,:wall_flamegraph,:allocation_flamegraph,:allocation_pie,:allocation_lines)
    (source_sha256=diagnostic_entry["source_sha256"],runtime=get(diagnostic_record,"runtime",nothing),workload=diagnostic_model.options["feature"],version=diagnostic_model.options["selected_version"],new_measurement=false)
end

# ╔═╡ b047a994-7174-4941-a972-000000000031
notebook_plot(diagnostic_model)

# ╔═╡ b047a994-7174-4941-a972-000000000032
md"""## Read the result before changing code
A passing oracle establishes only the selected inputs. A completed measurement is not a passing regression budget. Keep the fixture, resolved dependencies, runtime and thread settings with every conclusion. Inspect raw units and sample populations; confirm a suspected change with a small repeated release pair. Profiles add overhead and should be collected separately from ordinary timing.

Saved reports can be opened through the Julia REPL, VS Code, Web controller or Pluto. The recorded views in this file stay available without downloading a website or launching workers."""

